package paternsTUF;

public class Pattern3 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		Pattern3(5);
	}
	public static void Pattern3(int n) {
		for(int i=0;i<=n;i++) {
			for(int j=1;j<=i;j++) {
				System.out.print(j+" ");
			} 
			System.out.println();
		}
	}
	

}
